"""Retry policy and executor definitions for billing."""

from dataclasses import dataclass
from typing import Protocol


@dataclass(frozen=True)
class InvoiceRetryPolicy:
    """Retry policy for invoice charge attempts."""

    initial_delay_seconds: int
    max_attempts: int
    backoff_multiplier: int = 2


class RetryExecutor(Protocol):
    """Executes a single charge attempt for an invoice."""

    def execute(self, invoice: dict) -> dict:
        """Attempt to charge the invoice and return the provider result."""
        ...


class RetryPolicyProvider(Protocol):
    """Selects the retry policy to use for a given invoice."""

    def get_policy(self, invoice: dict) -> InvoiceRetryPolicy:
        """Return the retry policy for the invoice."""
        ...


def load_invoice_retry_policy() -> InvoiceRetryPolicy:
    """Load the default invoice retry policy."""

    return InvoiceRetryPolicy(initial_delay_seconds=30, max_attempts=5, backoff_multiplier=2)

